#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> pancakeSort(vector<int>& A) {
        vector<int> result;
        int n = A.size();

        for (int i = n; i > 1; --i) {
            int maxPos = max_element(A.begin(), A.begin() + i) - A.begin();
            if (maxPos == i - 1) continue;

            if (maxPos > 0) {
                reverse(A.begin(), A.begin() + maxPos + 1);
                result.push_back(maxPos + 1);
            }
            reverse(A.begin(), A.begin() + i);
            result.push_back(i);
        }

        return result;
    }
};
